SELECT Cia AS cia, COUNT(*) AS filas,
  COUNT(DISTINCT IdTercero) AS terceros_distintos
FROM dbo.clientes GROUP BY Cia ORDER BY Cia;

SELECT 'La Nieve' AS empresa, COUNT(DISTINCT Cod_Marca) AS marcas FROM dbo.NMSVMarca
UNION ALL
SELECT 'Unimarka', COUNT(DISTINCT Cod_Marca) FROM dbo.UMSVMarca;

SELECT 'La Nieve' AS empresa, COUNT(*) AS casas_comerciales FROM dbo.NMSVCasasComerciales
UNION ALL
SELECT 'Unimarka', COUNT(*) FROM dbo.UMSVCasasComerciales;

SELECT COUNT(DISTINCT [Nit Cliente]) AS clientes_con_compras_90d
FROM dbo.VentasBAT_NV
WHERE Fecha >= DATEADD(day, -90, CAST(GETDATE() AS date));
